import os, shutil, subprocess, sys, tempfile
R = os.getcwd()
mod = os.path.join(tempfile.mkdtemp(), 'mod')
shutil.copytree(R + '/.claude/skills/kbmon-pane', mod)
TEST = r"""import { expect, mock, test } from 'claude-code/testing'

test('a needs-you row cut at the pane width is no news when --status all gives no line', async ($, on) => {
  const clock = mock.clock(on)
  let needs = 'nothing'
  let onceRow = 'nothing'
  let broken = false
  const notified: string[] = []
  const run = (stdout: string) => ({ value: { exitCode: 0, stdout, stderr: '' } })
  on('process.run', ($, e) => {
    const argv = e.argv as string[]
    if (argv.includes('--receipt')) {
      return run(JSON.stringify({ line: 'kbmon: no alert on querylog; needs you: 1', fingerprint: 'f1' }))
    }
    if (argv.includes('--status')) {
      return run(broken ? 'sessions: none\n' : `needs you: ${needs}\nsessions: none\n`)
    }
    return run(`kbmon · 2026-10-24 10:00\nneeds you: ${broken ? onceRow : needs}\n\nkb: 1 root\n`)
  })
  on('ui.notify', ($, e) => {
    notified.push(e.text)

    return { value: { isSent: true, channel: 'terminal_bell' } }
  })
  on('ui.toast', () => ({ value: undefined }))
  on('ui.open', () => ({ value: { isPlaced: true } }))
  on('command.register', () => ({ value: undefined }))
  on('session.start', () => ({ cwd: '/work' }))

  const step = async (line: string, told: number) => {
    needs = line
    await clock.advance(60000)
    await clock.settle()
    expect(notified.length).toBe(told)
  }

  await $.session.start({ surface: 'terminal', isInteractive: true, cwd: '/work' })
  await clock.advance(2000)
  await clock.settle()

  await step('SP-aaaaaaaa gate start', 0)
  // --status all answers without a needs-you line, so the mod falls back to the pane row, cut at the width
  broken = true
  onceRow = 'needs you: SP-aaaaaaaa gate start; not r…'
  await step('SP-aaaaaaaa gate start', 0)
})
"""
open(os.path.join(mod, 'planted.test.ts'), 'w', encoding='utf-8').write(TEST)
def claude(*args):
    for d in os.environ.get('PATH', '').split(os.pathsep):
        p = os.path.join(d, 'claude')
        if os.path.isfile(p) and os.access(p, os.X_OK):
            r = subprocess.run([p, *args], capture_output=True, text=True, timeout=240)
            if 'not run from this spelling' not in r.stdout + r.stderr:
                return r
    print('no claude binary that runs plugin test')
    sys.exit(1)
r = claude('plugin', 'test', mod)
print((r.stdout + r.stderr)[-1500:])
sys.exit(1 if r.returncode != 0 else 0)
